class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        if len(word) <= 1:
            return 0
        
        operations = 0
        i = 0
        
        while i < len(word) - 1:
            # Check if current and next character are almost-equal
            if abs(ord(word[i]) - ord(word[i + 1])) <= 1:
                operations += 1
                # Skip the next character since we've "changed" it
                i += 2
            else:
                i += 1
        
        return operations
